using System;
using System.Linq;
using System.Collections.Generic;
using System.Runtime.InteropServices;
namespace DesktopBox {
// Explicit isolated diagnostic: exercises only this program's own temporary icon; late-observer test explicitly clears cached version before a real NIM_MODIFY.
public sealed class TrayFixture:System.Windows.Forms.NativeWindow,IDisposable {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct Data {public uint Size;public IntPtr Window;public uint Id,Flags,Callback;public IntPtr Icon;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=128)]public string Tip;public uint State,Mask;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=256)]public string Info;public uint Version;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=64)]public string Title;public uint InfoFlags;public Guid Guid;public IntPtr Balloon;}
 [DllImport("shell32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool Shell_NotifyIcon(uint operation,ref Data data);
 public sealed class Event {public uint Code,Id;public long Position;}
 public readonly List<Event> Events=new List<Event>();Data data;bool removed;
 public TrayFixture(){CreateHandle(new System.Windows.Forms.CreateParams{Caption="rushbin temporary tray test",ClassName="STATIC",Style=unchecked((int)0x80000000),ExStyle=0x80});data=new Data{Size=(uint)Marshal.SizeOf(typeof(Data)),Window=Handle,Id=4321,Flags=1|2|4,Callback=0x85fe,Icon=System.Drawing.SystemIcons.Information.Handle,Tip="rushbin 临时托盘验收",Info="",Title="",Version=4};if(!Shell_NotifyIcon(0,ref data))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());if(!Shell_NotifyIcon(4,ref data))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}
 public void UpdateTip(){data.Flags=4;data.Tip="rushbin 临时托盘验收 已更新";if(!Shell_NotifyIcon(1,ref data))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}
 public void RefreshFull(){data.Flags=7;data.Version=4;if(!Shell_NotifyIcon(1,ref data))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}
 public void EmptyBalloonTimeout(){data.Flags=4|16;data.Version=3;data.Info="";if(!Shell_NotifyIcon(1,ref data))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}
 public void Remove(){if(removed)return;Shell_NotifyIcon(2,ref data);removed=true;}
 protected override void WndProc(ref System.Windows.Forms.Message msg){if(msg.Msg==0x85fe){uint lp=unchecked((uint)msg.LParam.ToInt64());Events.Add(new Event{Code=lp&0xffff,Id=lp>>16,Position=msg.WParam.ToInt64()});return;}base.WndProc(ref msg);}
 public void Dispose(){Remove();DestroyHandle();}
 public static async void Run(TrayMirror mirror){var checks=new Dictionary<string,bool>();try{using(var fixture=new TrayFixture()){await System.Threading.Tasks.Task.Delay(550);var item=mirror.Items.FirstOrDefault(i=>i.Window==fixture.Handle);checks["registered"]=item!=null;checks["version4"]=item!=null&&item.Version==4;if(item==null)throw new InvalidOperationException("临时图标未同步");var point=new System.Windows.Point(123,456);foreach(string action in new[]{"left","right","double","middle"})mirror.Action(item,action,point);await System.Threading.Tasks.Task.Delay(120);checks["leftSelect"]=fixture.Events.Any(e=>e.Code==0x400&&e.Id==4321);checks["rightContextMenu"]=fixture.Events.Any(e=>e.Code==0x7b&&e.Id==4321);checks["doubleClick"]=fixture.Events.Any(e=>e.Code==0x203&&e.Id==4321);checks["middleClick"]=fixture.Events.Any(e=>e.Code==0x208&&e.Id==4321);checks["screenCoordinates"]=fixture.Events.All(e=>e.Position==((456L<<16)|123));fixture.UpdateTip();await System.Threading.Tasks.Task.Delay(350);checks["updated"]=mirror.Items.Any(i=>i.Window==fixture.Handle&&i.Tip.EndsWith("已更新"));item.Version=0;item.VersionConfirmed=false;fixture.RefreshFull();await System.Threading.Tasks.Task.Delay(350);checks["lateObserverVersionFromModify"]=mirror.Items.Any(i=>i.Window==fixture.Handle&&i.Version==4&&!i.VersionConfirmed);fixture.EmptyBalloonTimeout();await System.Threading.Tasks.Task.Delay(350);checks["balloonTimeoutDoesNotChangeVersion"]=mirror.Items.Any(i=>i.Window==fixture.Handle&&i.Version==4);fixture.Remove();await System.Threading.Tasks.Task.Delay(350);checks["removed"]=!mirror.Items.Any(i=>i.Window==fixture.Handle);Write(new{time=DateTimeOffset.Now.ToString("o"),passed=checks.Values.All(x=>x),checks,events=fixture.Events.ToArray(),scope="Actual Shell_NotifyIcon add/set-version/modify/delete and callback round trip; only this program's own temporary icon; late-observer test explicitly clears cached version before a real NIM_MODIFY"});}}catch(Exception ex){Write(new{time=DateTimeOffset.Now.ToString("o"),passed=false,checks,error=ex.ToString()});}}
 static void Write(object result){System.IO.File.WriteAllText(System.IO.Path.Combine(Program.S.Root,"tray-native-roundtrip.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(result),System.Text.Encoding.UTF8);}
}
}
